  };
}

function mnNormalizePlugins(value) {
  if (!Array.isArray(value)) return [];
  const seen = new Set();
  return value.slice(0, 30).map(mnNormalizePlugin).filter(plugin => {
    if (seen.has(plugin.id)) return false;
    seen.add(plugin.id);
